INSERT INTO plot_points (universe_slug, id, work_slug, character_id, arc_id, at, text) VALUES
  ('star-wars', 'yja-0', 'young-jedi-adventures', 'kai-brightstar', 'yja-tempel', 1, 'Beginnt seine Ausbildung im Jedi-Tempel des Hochrepublik-Zeitalters.'),
  ('star-wars', 'yja-1', 'young-jedi-adventures', 'kai-brightstar', 'yja-freundschaft', 5, 'Lernt, dass wahre Jedi-Stärke aus Zusammenhalt statt Alleingang kommt.'),
  ('star-wars', 'yja-2', 'young-jedi-adventures', 'lys-solay', 'yja-freundschaft', 3, 'Hilft einem verängstigten Wesen, sich der Gruppe anzuschließen.'),
  ('star-wars', 'yja-3', 'young-jedi-adventures', 'nubs', 'yja-tempel', 2, 'Sorgt trotz fehlender Worte für den Zusammenhalt der jungen Padawane.'),
  ('star-wars', 'acolyte-0', 'the-acolyte', 'mae', 'acolyte-schwestern', 1, 'Beginnt eine Mordserie an den Jedi, die einst ihr Zuhause zerstörten.'),
  ('star-wars', 'acolyte-1', 'the-acolyte', 'osha', 'acolyte-schwestern', 3, 'Wird fälschlich der Verbrechen ihrer verschollen geglaubten Zwillingsschwester verdächtigt.'),
  ('star-wars', 'acolyte-2', 'the-acolyte', 'sol', 'acolyte-jedi', 6, 'Gesteht Osha, was auf Brendok wirklich geschah.'),
  ('star-wars', 'acolyte-3', 'the-acolyte', 'qimir', 'acolyte-schatten', 7, 'Enttarnt sich als heimlicher Sith-Lehrer im Hintergrund.'),
  ('star-wars', 'acolyte-4', 'the-acolyte', 'osha', 'acolyte-schatten', 8, 'Wendet sich nach dem Verlust ihrer Schwester der dunklen Seite zu.'),
  ('star-wars', 'episode-i-0', 'episode-i', 'qui-gon', 'i-blockade', 6, 'Entkommt mit Obi-Wan dem Giftgasangriff auf dem Schiff der Handelsföderation.'),
  ('star-wars', 'episode-i-1', 'episode-i', 'jar-jar', 'i-blockade', 13, 'Wird von Qui-Gon gerettet und führt die Jedi in die Unterwasserstadt Otoh Gunga.'),
  ('star-wars', 'episode-i-2', 'episode-i', 'padme', 'i-blockade', 25, 'Flieht als Zofe getarnt mit den Jedi von Naboo.'),
  ('star-wars', 'episode-i-3', 'episode-i', 'qui-gon', 'i-auserwaehlter', 40, 'Entdeckt auf Tatooine den Sklavenjungen Anakin und seine starke Verbindung zur Macht.'),
  ('star-wars', 'episode-i-4', 'episode-i', 'anakin', 'i-auserwaehlter', 60, 'Gewinnt das Podrennen von Boonta Eve und damit seine Freiheit.'),
  ('star-wars', 'episode-i-5', 'episode-i', 'anakin', 'i-auserwaehlter', 68, 'Muss seine Mutter zurücklassen, um Jedi zu werden.'),
  ('star-wars', 'episode-i-6', 'episode-i', 'maul', 'i-sith', 70, 'Greift Qui-Gon kurz vor dem Abflug von Tatooine an.'),
  ('star-wars', 'episode-i-7', 'episode-i', 'palpatine', 'i-sith', 80, 'Überredet die Königin zum Misstrauensvotum gegen Kanzler Valorum.'),
  ('star-wars', 'episode-i-8', 'episode-i', 'qui-gon', 'i-auserwaehlter', 88, 'Scheitert vor dem Jedi-Rat mit der Bitte, Anakin auszubilden.'),
  ('star-wars', 'episode-i-9', 'episode-i', 'padme', 'i-blockade', 100, 'Gibt sich vor Boss Nass als Königin zu erkennen und bittet die Gungans um Hilfe.'),
  ('star-wars', 'episode-i-10', 'episode-i', 'jar-jar', 'i-blockade', 110, 'Zieht als General mit der Gungan-Armee gegen die Droiden.'),
  ('star-wars', 'episode-i-11', 'episode-i', 'maul', 'i-sith', 118, 'Tötet Qui-Gon im Duell im Generatorkomplex von Theed.'),
  ('star-wars', 'episode-i-12', 'episode-i', 'anakin', 'i-blockade', 120, 'Zerstört im Raumkampf eher zufällig das Droidenkontrollschiff.'),
  ('star-wars', 'episode-i-13', 'episode-i', 'obi-wan', 'i-sith', 121, 'Besiegt Maul und verspricht dem sterbenden Qui-Gon, Anakin auszubilden.'),
  ('star-wars', 'episode-i-14', 'episode-i', 'palpatine', 'i-sith', 128, 'Wird zum Obersten Kanzler der Republik gewählt.'),
  ('star-wars', 'episode-ii-0', 'episode-ii', 'padme', 'ii-attentat', 3, 'Überlebt bei der Landung auf Coruscant ein Bombenattentat.'),
  ('star-wars', 'episode-ii-1', 'episode-ii', 'anakin', 'ii-attentat', 18, 'Jagt mit Obi-Wan die Attentäterin durch die Häuserschluchten von Coruscant.'),
  ('star-wars', 'episode-ii-2', 'episode-ii', 'obi-wan', 'ii-klonkrieg', 38, 'Stößt auf Kamino auf eine geheime Klonarmee für die Republik.'),
  ('star-wars', 'episode-ii-3', 'episode-ii', 'jango', 'ii-attentat', 50, 'Liefert sich mit Obi-Wan einen Kampf auf den Landeplattformen von Kamino.'),
  ('star-wars', 'episode-ii-4', 'episode-ii', 'padme', 'ii-liebe', 60, 'Gesteht sich ihre Gefühle für Anakin ein, weist ihn aber zurück.'),
  ('star-wars', 'episode-ii-5', 'episode-ii', 'anakin', 'ii-liebe', 78, 'Findet seine sterbende Mutter bei den Tusken und rächt sich an dem ganzen Stamm.'),
