  ('star-wars', 'episode-ix-0', 'episode-ix', 'kylo', 'ix-imperator', 3, 'Findet auf Exegol den totgeglaubten Imperator.'),
  ('star-wars', 'episode-ix-1', 'episode-ix', 'palpatine', 'ix-imperator', 5, 'Verspricht Kylo eine ganze Flotte, wenn er Rey tötet.'),
  ('star-wars', 'episode-ix-2', 'episode-ix', 'rey', 'ix-skywalker', 10, 'Trainiert unter Leias Anleitung als Jedi.'),
  ('star-wars', 'episode-ix-3', 'episode-ix', 'poe', 'ix-suche', 20, 'Bricht mit Rey, Finn und Chewbacca nach Pasaana auf.'),
  ('star-wars', 'episode-ix-4', 'episode-ix', 'rey', 'ix-suche', 38, 'Glaubt, Chewbacca mit einem Machtblitz getötet zu haben.'),
  ('star-wars', 'episode-ix-5', 'episode-ix', 'kylo', 'ix-suche', 55, 'Enthüllt Rey, dass sie Palpatines Enkelin ist.'),
  ('star-wars', 'episode-ix-6', 'episode-ix', 'finn', 'ix-suche', 65, 'Findet auf Kef Bir ehemalige Sturmtruppler, die desertiert sind.'),
  ('star-wars', 'episode-ix-7', 'episode-ix', 'leia', 'ix-skywalker', 83, 'Ruft ihren Sohn mit letzter Kraft zurück und stirbt.'),
  ('star-wars', 'episode-ix-8', 'episode-ix', 'rey', 'ix-skywalker', 84, 'Besiegt Kylo auf den Trümmern des Todessterns – und heilt ihn.'),
  ('star-wars', 'episode-ix-9', 'episode-ix', 'kylo', 'ix-skywalker', 88, 'Wirft sein Lichtschwert fort und wird wieder zu Ben Solo.'),
  ('star-wars', 'episode-ix-10', 'episode-ix', 'rey', 'ix-skywalker', 92, 'Wird auf Ahch-To von Lukes Geist zurück in den Kampf geschickt.'),
  ('star-wars', 'episode-ix-11', 'episode-ix', 'poe', 'ix-imperator', 105, 'Führt die Flotte der Freien Galaxis gegen die Final Order.'),
  ('star-wars', 'episode-ix-12', 'episode-ix', 'palpatine', 'ix-imperator', 118, 'Entzieht Rey und Ben die Kraft der Dyade.'),
  ('star-wars', 'episode-ix-13', 'episode-ix', 'rey', 'ix-imperator', 123, 'Wehrt mit den Stimmen der Jedi die Blitze des Imperators ab.'),
  ('star-wars', 'episode-ix-14', 'episode-ix', 'kylo', 'ix-skywalker', 128, 'Gibt Rey sein Leben und stirbt.'),
  ('star-wars', 'episode-ix-15', 'episode-ix', 'rey', 'ix-skywalker', 138, 'Nennt sich auf Tatooine Rey Skywalker.');
