  ('mcu', 'pp-si-1', 'secret-invasion', 'fury-si', 'si-fury', 1, 'Kehrt nach Jahren im All auf die Erde zurück.'),
  ('mcu', 'pp-si-2', 'secret-invasion', 'gravik-si', 'si-skrulls', 1, 'Plant mit Skrull-Rebellen, einen Krieg zwischen den Großmächten auszulösen.'),
  ('mcu', 'pp-si-3', 'secret-invasion', 'talos-si', 'si-skrulls', 4, 'Wird von Gravik getötet.'),
  ('mcu', 'pp-si-4', 'secret-invasion', 'gravik-si', 'si-skrulls', 6, 'Stirbt im Kampf gegen die mit dem Harvest gestärkte G''iah.'),
  ('mcu', 'pp-aq-1', 'ant-man-quantumania', 'cassie-aq', 'aq-quantenreich', 10, 'Sendet ein Signal ins Quantenreich und zieht die ganze Familie hinein.'),
  ('mcu', 'pp-aq-2', 'ant-man-quantumania', 'kang-aq', 'aq-kang', 55, 'Will mit Scotts Hilfe den Mehrfachkern für seine Flucht zurückholen.'),
  ('mcu', 'pp-aq-3', 'ant-man-quantumania', 'scott-aq', 'aq-kang', 115, 'Stellt sich Kang im Kampf am Mehrfachkern.'),
  ('mcu', 'pp-g3-1', 'guardians-of-the-galaxy-vol-3', 'rocket-g3', 'g3-rocket', 10, 'Wird von Adam Warlock schwer verletzt und schwebt in Lebensgefahr.'),
  ('mcu', 'pp-g3-2', 'guardians-of-the-galaxy-vol-3', 'peter-g3', 'g3-rocket', 40, 'Sucht mit den Guardians den Passcode, der Rocket retten kann.'),
  ('mcu', 'pp-g3-3', 'guardians-of-the-galaxy-vol-3', 'high-evolutionary-g3', 'g3-high-evolutionary', 90, 'Will Rocket zurück, um das Geheimnis seiner Intelligenz zu entschlüsseln.'),
  ('mcu', 'pp-g3-4', 'guardians-of-the-galaxy-vol-3', 'rocket-g3', 'g3-high-evolutionary', 130, 'Rettet die gefangenen Kinder und Tiere vor dem High Evolutionary.'),
  ('mcu', 'pp-g3-5', 'guardians-of-the-galaxy-vol-3', 'peter-g3', 'g3-rocket', 145, 'Verlässt die Guardians und kehrt zu seinem Großvater auf die Erde zurück.'),
  ('mcu', 'pp-tm-1', 'the-marvels', 'carol-tm', 'tm-verschraenkt', 10, 'Tauscht bei jedem Einsatz ihrer Kräfte den Ort mit Kamala und Monica.'),
  ('mcu', 'pp-tm-2', 'the-marvels', 'kamala-tm', 'tm-verschraenkt', 15, 'Kämpft plötzlich an der Seite ihres Idols Captain Marvel.'),
  ('mcu', 'pp-tm-3', 'the-marvels', 'carol-tm', 'tm-dar-benn', 50, 'Muss sich Dar-Benn stellen, die fremde Welten plündert, um Hala zu retten.'),
  ('mcu', 'pp-tm-4', 'the-marvels', 'monica-tm', 'tm-dar-benn', 95, 'Schließt den Riss zwischen den Universen und strandet in einer anderen Realität.'),
  ('mcu', 'pp-aaa-1', 'agatha-all-along', 'agatha-aaa', 'aaa-weg', 1, 'Befreit sich aus Wandas Bann über Westview.'),
  ('mcu', 'pp-aaa-2', 'agatha-all-along', 'teen-aaa', 'aaa-weg', 2, 'Drängt Agatha, einen Hexenzirkel für den Weg der Hexen zu gründen.'),
  ('mcu', 'pp-aaa-3', 'agatha-all-along', 'teen-aaa', 'aaa-teen', 5, 'Erkennt, dass er die Seele von Wandas Sohn Billy in sich trägt.'),
  ('mcu', 'pp-aaa-4', 'agatha-all-along', 'rio-aaa', 'aaa-teen', 7, 'Enttarnt sich als der Tod selbst.'),
  ('mcu', 'pp-aaa-5', 'agatha-all-along', 'agatha-aaa', 'aaa-teen', 8, 'Opfert sich, um Billy vor dem Tod zu schützen.'),
  ('mcu', 'pp-ih-1', 'ironheart', 'riri-ih', 'ih-anzug', 1, 'Fliegt vom MIT und kehrt nach Chicago zurück.'),
  ('mcu', 'pp-ih-2', 'ironheart', 'parker-ih', 'ih-hood', 1, 'Holt Riri in seine Bande, damit sie ihren Anzug finanzieren kann.'),
  ('mcu', 'pp-ih-3', 'ironheart', 'natalie-ih', 'ih-anzug', 3, 'Hilft Riri als KI mit der Persönlichkeit ihrer verstorbenen Freundin.'),
  ('mcu', 'pp-ih-4', 'ironheart', 'riri-ih', 'ih-hood', 6, 'Lässt sich auf einen Handel mit Mephisto ein, um Natalie zurückzuholen.'),
  ('mcu', 'pp-dw-1', 'deadpool-und-wolverine', 'wade-dw', 'dw-tva', 10, 'Erfährt von der TVA, dass seine Welt ohne ihren Anker Logan untergehen wird.'),
  ('mcu', 'pp-dw-2', 'deadpool-und-wolverine', 'logan-dw', 'dw-tva', 25, 'Wird von Wade aus einer Zeitlinie geholt, in der er versagt hat.'),
  ('mcu', 'pp-dw-3', 'deadpool-und-wolverine', 'cassandra-dw', 'dw-leere', 60, 'Herrscht in der Leere über die ausrangierten Figuren des Multiversums.'),
  ('mcu', 'pp-dw-4', 'deadpool-und-wolverine', 'wade-dw', 'dw-leere', 115, 'Stoppt mit Logan den Zeitauslöscher von Paradox.'),
  ('mcu', 'pp-dba-1', 'daredevil-born-again', 'matt-dba', 'dba-buergermeister', 1, 'Legt nach Foggys Tod das Daredevil-Kostüm ab.'),
  ('mcu', 'pp-dba-2', 'daredevil-born-again', 'fisk-dba', 'dba-buergermeister', 2, 'Wird zum Bürgermeister von New York gewählt.'),
  ('mcu', 'pp-dba-3', 'daredevil-born-again', 'frank-dba', 'dba-muse', 4, 'Wirft Matt vor, sich mit seinem Rückzug selbst zu belügen.'),
  ('mcu', 'pp-dba-4', 'daredevil-born-again', 'matt-dba', 'dba-muse', 6, 'Zieht wieder als Daredevil los, um den Serienkiller Muse zu stoppen.'),
  ('mcu', 'pp-dba-5', 'daredevil-born-again', 'fisk-dba', 'dba-buergermeister', 9, 'Verhängt das Kriegsrecht und stellt eine Anti-Vigilanten-Einheit auf.'),
  ('mcu', 'pp-bnw-1', 'captain-america-brave-new-world', 'ross-bnw', 'bnw-attentat', 10, 'Wird Präsident und bittet Sam, die Avengers neu aufzubauen.'),
  ('mcu', 'pp-bnw-2', 'captain-america-brave-new-world', 'isaiah-bnw', 'bnw-attentat', 20, 'Schießt unter fremder Kontrolle auf den Präsidenten.'),
  ('mcu', 'pp-bnw-3', 'captain-america-brave-new-world', 'sam-bnw', 'bnw-attentat', 60, 'Findet heraus, dass Samuel Sterns hinter dem Anschlag steckt.'),
  ('mcu', 'pp-bnw-4', 'captain-america-brave-new-world', 'ross-bnw', 'bnw-red-hulk', 95, 'Verwandelt sich vor dem Weißen Haus in den Red Hulk.'),
  ('mcu', 'pp-bnw-5', 'captain-america-brave-new-world', 'sam-bnw', 'bnw-red-hulk', 105, 'Stellt sich als Captain America dem Red Hulk.'),
  ('mcu', 'pp-wm-1', 'wonder-man', 'simon-wm', 'wm-casting', 1, 'Bewirbt sich um die Hauptrolle im Remake von „Wonder Man“.'),
  ('mcu', 'pp-wm-2', 'wonder-man', 'simon-wm', 'wm-dodc', 1, 'Verbirgt seine Kräfte, weil Superkräfte ihn in Hollywood unvermittelbar machen würden.'),
  ('mcu', 'pp-wm-3', 'wonder-man', 'trevor-wm', 'wm-dodc', 2, 'Freundet sich mit Simon an, arbeitet aber heimlich für Damage Control.'),
  ('mcu', 'pp-tb-1', 'thunderbolts', 'valentina-tb', 'tb-falle', 15, 'Schickt ihre eigenen Agenten in eine Falle, um Beweise zu vernichten.'),
  ('mcu', 'pp-tb-2', 'thunderbolts', 'yelena-tb', 'tb-falle', 25, 'Trifft im Tresor auf Ghost, John Walker und Taskmaster.'),
  ('mcu', 'pp-tb-3', 'thunderbolts', 'bob-tb', 'tb-void', 90, 'Wird zu Sentry und entfesselt seine dunkle Seite, die Void.'),
  ('mcu', 'pp-tb-4', 'thunderbolts', 'yelena-tb', 'tb-void', 115, 'Holt Bob aus der Dunkelheit, indem sie ihre eigene Leere mit ihm teilt.'),
  ('mcu', 'pp-tb-5', 'thunderbolts', 'valentina-tb', 'tb-void', 125, 'Präsentiert das Team öffentlich als die New Avengers.'),
  ('mcu', 'pp-ff-1', 'fantastic-four-first-steps', 'sue-ff', 'ff-familie', 10, 'Erfährt nach Jahren des Wartens, dass sie schwanger ist.'),
  ('mcu', 'pp-ff-2', 'fantastic-four-first-steps', 'galactus-ff', 'ff-galactus', 40, 'Verlangt Sues ungeborenen Sohn Franklin als Preis für die Verschonung der Erde.'),
  ('mcu', 'pp-ff-3', 'fantastic-four-first-steps', 'reed-ff', 'ff-galactus', 85, 'Plant, Galactus mit einem gewaltigen Teleporter in eine andere Galaxie zu versetzen.'),
  ('mcu', 'pp-ff-4', 'fantastic-four-first-steps', 'sue-ff', 'ff-galactus', 105, 'Drängt Galactus mit ihren Kräften zurück, stirbt und wird von Franklin wiederbelebt.');
