INSERT INTO plot_points (universe_slug, id, work_slug, character_id, arc_id, at, text) VALUES
  ('star-trek', 'pp-ent-1', 'star-trek-enterprise', 'archer-ent', 'ent-xindi', 40, 'Führt die Enterprise NX-01 in die gefährliche Expanse, um die Xindi-Waffe zu finden.'),
  ('star-trek', 'pp-ent-2', 'star-trek-enterprise', 'tpol-ent', 'ent-foederation', 70, 'Hilft als vulkanische Wissenschaftsoffizierin, Misstrauen zwischen Menschen und Vulkaniern abzubauen.'),
  ('star-trek', 'pp-ent-3', 'star-trek-enterprise', 'trip-ent', 'ent-xindi', 50, 'Verliert bei einem Xindi-Angriff auf die Erde seine eigene Schwester.'),
  ('star-trek', 'pp-disc-1', 'star-trek-discovery', 'burnham-disc', 'disc-krieg', 10, 'Wird nach einer folgenschweren Meuterei degradiert und zur Discovery versetzt.'),
  ('star-trek', 'pp-disc-2', 'star-trek-discovery', 'saru-disc', 'disc-spore', 30, 'Nutzt als Kelpianer seine besonderen Sinne, um die Crew vor Gefahren zu warnen.'),
  ('star-trek', 'pp-snw-1', 'star-trek-strange-new-worlds', 'pike-snw', 'snw-pike', 15, 'Weiß bereits um sein eigenes tragisches Schicksal, führt die Enterprise aber unbeirrt weiter.'),
  ('star-trek', 'pp-snw-2', 'star-trek-strange-new-worlds', 'spock-snw', 'snw-pike', 20, 'Dient als junger Wissenschaftsoffizier lange vor Kirks Kommando auf der Enterprise.'),
  ('star-trek', 'pp-tos-1', 'star-trek-the-original-series', 'kirk-tos', 'tos-erkundung', 30, 'Führt die Enterprise auf ihrer Fünf-Jahres-Mission durch unbekanntes Weltall.'),
  ('star-trek', 'pp-tos-2', 'star-trek-the-original-series', 'spock-tos', 'tos-erkundung', 25, 'Bringt als erster vulkanischer Offizier Logik in Kirks impulsive Entscheidungen.'),
  ('star-trek', 'pp-tos-3', 'star-trek-the-original-series', 'mccoy-tos', 'tos-klingonen', 40, 'Streitet als Chefarzt regelmäßig mit Spock über Logik gegen Gefühl.'),
  ('star-trek', 'pp-tos-4', 'star-trek-the-original-series', 'uhura-tos', 'tos-klingonen', 35, 'Hält als Kommunikationsoffizierin den Kontakt zur Sternenflotte in jeder Krise aufrecht.'),
  ('star-trek', 'pp-tmp-1', 'star-trek-the-motion-picture', 'kirk-tmp', 'tmp-vger', 100, 'Übernimmt erneut das Kommando der Enterprise, um die Erde vor V''Ger zu retten.'),
  ('star-trek', 'pp-tmp-2', 'star-trek-the-motion-picture', 'spock-tmp', 'tmp-vger', 90, 'Erkennt in V''Ger eine frühere irdische Sonde auf der Suche nach ihrem Schöpfer.'),
  ('star-trek', 'pp-wok-1', 'star-trek-ii-wrath-of-khan', 'khan-wok', 'wok-khan', 20, 'Sucht nach Jahren der Verbannung blutige Rache an Kirk.'),
  ('star-trek', 'pp-wok-2', 'star-trek-ii-wrath-of-khan', 'spock-wok', 'wok-khan', 105, 'Opfert sich, um den Warpkern zu reparieren und die Enterprise zu retten.'),
  ('star-trek', 'pp-sfs-1', 'star-trek-iii-search-for-spock', 'kirk-sfs', 'sfs-spock', 90, 'Opfert die Enterprise selbst, um Spocks Körper und Seele zu retten.'),
  ('star-trek', 'pp-sfs-2', 'star-trek-iii-search-for-spock', 'spock-sfs', 'sfs-spock', 95, 'Wird auf Vulkan durch das Fal-tor-pan-Ritual wiedervereint mit seinem Katra.'),
  ('star-trek', 'pp-vh-1', 'star-trek-iv-voyage-home', 'kirk-vh', 'vh-wale', 60, 'Reist mit der Crew in die Vergangenheit, um Buckelwale in die Zukunft zu bringen.'),
  ('star-trek', 'pp-vh-2', 'star-trek-iv-voyage-home', 'spock-vh', 'vh-wale', 40, 'Kommuniziert im San Francisco des 20. Jahrhunderts erstmals wieder mit Walen.'),
  ('star-trek', 'pp-ff-1', 'star-trek-v-final-frontier', 'sybok-ff', 'ff-sybok', 50, 'Entführt die Enterprise auf der Suche nach dem Planeten Sha Ka Ree.'),
  ('star-trek', 'pp-ff-2', 'star-trek-v-final-frontier', 'kirk-ff', 'ff-sybok', 95, 'Stellt die vermeintliche Gottheit hinter der Suche infrage.'),
  ('star-trek', 'pp-uc-1', 'star-trek-vi-undiscovered-country', 'kirk-uc', 'uc-frieden', 100, 'Überwindet seinen Hass auf die Klingonen, um den Frieden zu retten.'),
  ('star-trek', 'pp-uc-2', 'star-trek-vi-undiscovered-country', 'chang-uc', 'uc-frieden', 60, 'Sabotiert als klingonischer General gezielt die Friedensverhandlungen.'),
  ('star-trek', 'pp-tng-1', 'star-trek-the-next-generation', 'picard-tng', 'tng-borg', 90, 'Wird von den Borg assimiliert und als Locutus gegen die Sternenflotte eingesetzt.'),
  ('star-trek', 'pp-tng-2', 'star-trek-the-next-generation', 'data-tng', 'tng-q', 20, 'Strebt als Android stetig danach, menschlicher zu werden.'),
  ('star-trek', 'pp-tng-3', 'star-trek-the-next-generation', 'worf-tng', 'tng-q', 30, 'Dient als erster klingonischer Offizier der Sternenflotte an Bord.'),
  ('star-trek', 'pp-tng-4', 'star-trek-the-next-generation', 'riker-tng', 'tng-q', 15, 'Lehnt wiederholt eigene Kommandoangebote ab, um bei der Enterprise zu bleiben.'),
  ('star-trek', 'pp-ds9-1', 'star-trek-deep-space-nine', 'sisko-ds9', 'ds9-bajor', 10, 'Übernimmt die Station Deep Space Nine, um Bajor beim Wiederaufbau zu helfen.'),
  ('star-trek', 'pp-ds9-2', 'star-trek-deep-space-nine', 'kira-ds9', 'ds9-bajor', 15, 'Wechselt vom bajoranischen Widerstand zur Zusammenarbeit mit der Sternenflotte.'),
  ('star-trek', 'pp-ds9-3', 'star-trek-deep-space-nine', 'odo-ds9', 'ds9-dominion', 120, 'Muss sich als Wechselbalg zwischen seinem Volk und seinen Freunden entscheiden.'),
  ('star-trek', 'pp-gen-1', 'star-trek-generations', 'soran-gen', 'gen-nexus', 20, 'Ist bereit, ganze Sonnensysteme zu zerstören, um in den Nexus zurückzukehren.'),
  ('star-trek', 'pp-gen-2', 'star-trek-generations', 'kirk-gen', 'gen-nexus', 100, 'Verlässt den paradiesischen Nexus noch einmal, um Picard zu helfen.'),
  ('star-trek', 'pp-gen-3', 'star-trek-generations', 'picard-gen', 'gen-nexus', 60, 'Trifft im Nexus auf einen aus der Zeit geholten Captain Kirk.'),
  ('star-trek', 'pp-voy-1', 'star-trek-voyager', 'janeway-voy', 'voy-heimreise', 10, 'Verschlägt es mit ihrem Schiff 70.000 Lichtjahre in den Delta-Quadranten.'),
  ('star-trek', 'pp-voy-2', 'star-trek-voyager', 'seven-voy', 'voy-borg', 90, 'Wird von der Crew von den Borg befreit und mühsam wieder resozialisiert.'),
  ('star-trek', 'pp-voy-3', 'star-trek-voyager', 'tuvok-voy', 'voy-heimreise', 20, 'Balanciert als vulkanischer Sicherheitschef Loyalität und Logik auf der langen Heimreise.'),
  ('star-trek', 'pp-fc-1', 'star-trek-first-contact', 'picard-fc', 'fc-zeitreise', 90, 'Verfolgt die Borg in der Zeit zurück, um Zephram Cochranes ersten Warpflug zu retten.'),
  ('star-trek', 'pp-fc-2', 'star-trek-first-contact', 'borg-queen-fc', 'fc-zeitreise', 70, 'Versucht, die Erde bereits vor der Gründung der Föderation zu assimilieren.'),
  ('star-trek', 'pp-fc-3', 'star-trek-first-contact', 'data-fc', 'fc-zeitreise', 80, 'Wird von der Borg-Königin mit menschlicher Haut in Versuchung geführt.'),
  ('star-trek', 'pp-ins-1', 'star-trek-insurrection', 'picard-ins', 'ins-baku', 60, 'Widersetzt sich einem Befehl, das Volk der Ba''ku umzusiedeln.'),
  ('star-trek', 'pp-ins-2', 'star-trek-insurrection', 'data-ins', 'ins-baku', 20, 'Gerät durch einen Defekt außer Kontrolle und enthüllt so die Verschwörung.'),
  ('star-trek', 'pp-nem-1', 'star-trek-nemesis', 'shinzon-nem', 'nem-shinzon', 30, 'Enthüllt sich als klonierter Doppelgänger Picards vom Planeten Remus.'),
  ('star-trek', 'pp-nem-2', 'star-trek-nemesis', 'picard-nem', 'nem-shinzon', 100, 'Stellt sich seinem eigenen Klon im entscheidenden Raumschiffduell.'),
  ('star-trek', 'pp-ld-1', 'star-trek-lower-decks', 'mariner-ld', 'ld-cerritos', 1, 'Dient als rebellische Fähnrich auf der U.S.S. Cerritos, deren Captain heimlich ihre Mutter ist.'),
  ('star-trek', 'pp-ld-2', 'star-trek-lower-decks', 'boimler-ld', 'ld-cerritos', 10, 'Nimmt eine Versetzung auf Captain Rikers U.S.S. Titan an.'),
  ('star-trek', 'pp-pro-1', 'star-trek-prodigy', 'dal-pro', 'pro-protostar', 1, 'Entdeckt mit anderen Gefangenen von Tars Lamora das verlassene Sternenflottenschiff Protostar.'),
  ('star-trek', 'pp-pro-2', 'star-trek-prodigy', 'gwyn-pro', 'pro-protostar', 2, 'Schließt sich als Tochter des Diviners der Crew an, die aus seinem Lager flieht.'),
  ('star-trek', 'pp-pro-3', 'star-trek-prodigy', 'janeway-pro', 'pro-protostar', 3, 'Bringt der jungen Crew als Trainingshologramm die Werte der Sternenflotte bei.'),
  ('star-trek', 'pp-pic-1', 'star-trek-picard', 'picard-pic', 'pic-synths', 10, 'Verlässt im Ruhestand die Sternenflotte aus Protest gegen das Synthetik-Verbot.'),
  ('star-trek', 'pp-pic-2', 'star-trek-picard', 'seven-pic', 'pic-synths', 25, 'Kämpft Jahre nach Voyager als Fenris-Rangerin gegen galaktisches Unrecht.');
